int RecoveryActorMean(const float *input,float *mean) {
float a[256],b[256];
for(int j=0;j<31;j++){if(!isfinite(input[j]))return -1;a[j]=input[j];}
for(int j=0;j<256;j++){float s=b0[j];for(int k=0;k<31;k++)s+=w0[j*31+k]*a[k];b[j]=s>=0?s:expm1f(s); }
for(int j=0;j<256;j++)a[j]=b[j];
for(int j=0;j<128;j++){float s=b1[j];for(int k=0;k<256;k++)s+=w1[j*256+k]*a[k];b[j]=s>=0?s:expm1f(s); }
for(int j=0;j<128;j++)a[j]=b[j];
for(int j=0;j<64;j++){float s=b2[j];for(int k=0;k<128;k++)s+=w2[j*128+k]*a[k];b[j]=s>=0?s:expm1f(s); }
for(int j=0;j<64;j++)a[j]=b[j];
for(int j=0;j<6;j++){float s=b3[j];for(int k=0;k<64;k++)s+=w3[j*64+k]*a[k];b[j]=tanhf(s);}
for(int j=0;j<6;j++)a[j]=b[j];
for(int j=0;j<6;j++){if(!isfinite(a[j]))return -2;mean[j]=a[j];}return 0;}
int RecoveryActorPhysical(const float *input,float *mean,float *physical){int r=RecoveryActorMean(input,mean);if(r)return r;return RLMotion31DecodeRecoveryMean(mean,physical);}
